import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Instalar y administrar plugins","description":"","frontmatter":{"title":"Instalar y administrar plugins","docId":"user.plugins.index","translationKey":"user.plugins.index","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2892162f1f2ec94f8e5072f6689382b3c32c8546f2ad667a4651c721f597e84a","translationRevision":"f44907654d53f5e696aa6044ac481d64d84947c293809c9dbda53b9d127a4b8d","order":10},"headers":[],"relativePath":"es/user/plugins/index.md","filePath":"es/user/plugins/index.md","lastUpdated":1795735295000}`),s={name:`es/user/plugins/index.md`};function c(a,o,s,c,l,u){let d=e(`TourFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="install-and-manage-plugins" tabindex="-1">Instalar y administrar plugins <a class="header-anchor" href="#install-and-manage-plugins" aria-label="Permalink to “Instalar y administrar plugins”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo y requisitos”">​</a></h2><p>Añade una integración, revisa el acceso solicitado y confirma que sus acciones funcionan. Necesitas un paquete de escritorio compatible con el sistema operativo, arquitectura y versión del host exigidos por el plugin. El catálogo remoto y las descargas requieren Internet; algunos servicios también necesitan <a href="./../cloud/account.html">sesión de Cloud</a>.</p><h2 id="review-before-enabling" tabindex="-1">Revisar antes de activar <a class="header-anchor" href="#review-before-enabling" aria-label="Permalink to “Revisar antes de activar”">​</a></h2><ol><li>Abre <strong>Plugins</strong> y consulta Installed, Explore o Updates. Explore solicita únicamente plugins. Las plantillas y perfiles se encuentran en <a href="./../automations/templates.html">Automations</a>.</li><li>Selecciona un plugin para revisar descripción, versión, compatibilidad y entorno de ejecución. Comprueba editor, capacidades y permisos; el nombre visible por sí solo no demuestra confianza.</li><li>Usa el flujo de instalación para inspeccionar la vista previa del paquete. Revisa versión exacta, información de firma, acceso solicitado y diferencias respecto a la versión instalada antes de confirmar.</li><li>Espera el resultado del trabajo de instalación. Descargar, instalar y activar son etapas distintas; una tarjeta del catálogo no significa que el plugin esté preparado.</li><li>Abre sus paneles Settings o Connection. Introduce dirección y credenciales únicamente en los campos previstos. Usa la comprobación de conexión declarada si existe.</li><li>Activa el plugin y comprueba si aparecen sus acciones o páginas. Crea una <a href="./../automations/first-rule.html">regla de registro</a> limitada antes de vincular una acción externa potente.</li></ol><p>Los plugins pueden ejecutar código nativo o procesos separados. Un proceso puede aislar un fallo, pero no constituye una zona aislada del sistema operativo. Instala software de editores confiables. Una firma válida identifica la procedencia del paquete revisado; no garantiza que todos sus efectos sean apropiados para tu flujo.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado y estado”">​</a></h2><p>Están disponibles la revisión de paquetes, los trabajos de instalación, las preferencias y la gestión de versiones. Las acciones concretas dependen del manifiesto instalado, las capacidades del host y el servicio externo. Los procesadores de eventos tienen un panel propio y pueden añadir campos de análisis opcionales; los campos originales siguen siendo distintos.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recuperación”">​</a></h2><p>Ante un fallo, lee el error del trabajo para identificar incompatibilidad, firma, entorno o descarga. Evita debilitar la verificación para eliminar un aviso. Si una actualización falla, revisa las versiones conservadas y usa la reversión cuando esté disponible. Comprueba automatizaciones dependientes antes de desactivar o desinstalar. Conserva <a href="./../preferences/backups.html">copias</a> de datos y configuración antes de eliminarlos.</p>`,10),t(d,{id:`plugin`,locale:`es`,title:`Demo de plugins`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Operaciones de línea de comandos <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Operaciones de línea de comandos”">​</a></h2><p>Cada operación de esta guía también está disponible desde la CLI: sin conexión, scriptable y apta para agentes. Las líneas de uso son sintaxis del parser y permanecen en inglés en todos los idiomas.</p><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools plugin list</code></td><td>listar los plugins instalados</td></tr><tr><td><code>tiktools plugin get &lt;id&gt;</code></td><td>leer un plugin</td></tr><tr><td><code>tiktools plugin install &lt;file.plugin&gt; [--replace] &amp;#124; plugin install &lt;id[@version]&amp;#124;url&gt; [--yes] [--no-wait] [--allow-unsigned]</code></td><td>instalar desde un archivo, id@version o url</td></tr><tr><td><code>tiktools plugin uninstall &lt;id&gt; [--purge]</code></td><td>desinstalar un plugin <strong>destructivo</strong></td></tr><tr><td><code>tiktools plugin search &lt;query&gt; [--category c] [--page N]</code></td><td>buscar paquetes en el registro</td></tr><tr><td><code>tiktools plugin inspect &lt;spec&gt;</code></td><td>inspeccionar una especificación de paquete antes de instalar</td></tr><tr><td><code>tiktools plugin outdated</code></td><td>listar los plugins instalados con actualizaciones disponibles</td></tr><tr><td><code>tiktools plugin update &lt;id&gt; [--version v] [--yes] [--no-wait]</code></td><td>actualizar un plugin</td></tr><tr><td><code>tiktools plugin update --all [--yes] [--no-wait]</code></td><td>actualizar todos los plugins desactualizados</td></tr><tr><td><code>tiktools plugin rollback &lt;id&gt; [version] [--no-wait]</code></td><td>volver a una versión anterior <strong>destructivo</strong></td></tr><tr><td><code>tiktools plugin versions &lt;id&gt;</code></td><td>listar las versiones disponibles de un plugin</td></tr><tr><td><code>tiktools plugin pin &lt;id&gt;</code></td><td>fijar un plugin a su versión actual</td></tr><tr><td><code>tiktools plugin unpin &lt;id&gt;</code></td><td>quitar la fijación de versión</td></tr><tr><td><code>tiktools plugin policy &lt;id&gt; [--channel stable&amp;#124;beta] [--auto off&amp;#124;notify&amp;#124;patch&amp;#124;minor]</code></td><td>establecer el canal y la política de autoactualización</td></tr><tr><td><code>tiktools plugin jobs</code></td><td>listar los trabajos de paquetes</td></tr><tr><td><code>tiktools plugin job &lt;job-id&gt;</code></td><td>inspeccionar un trabajo de paquete</td></tr><tr><td><code>tiktools plugin cancel &lt;job-id&gt;</code></td><td>cancelar un trabajo de paquete en curso <strong>destructivo</strong></td></tr><tr><td><code>tiktools plugin enable &lt;id&gt;</code></td><td>activar un plugin</td></tr><tr><td><code>tiktools plugin disable &lt;id&gt;</code></td><td>desactivar un plugin</td></tr><tr><td><code>tiktools plugin start &lt;id&gt;</code></td><td>iniciar un plugin</td></tr><tr><td><code>tiktools plugin stop &lt;id&gt;</code></td><td>detener un plugin <strong>destructivo</strong></td></tr><tr><td><code>tiktools plugin settings get &lt;id&gt;</code></td><td>leer la configuración de un plugin</td></tr><tr><td><code>tiktools plugin settings set &lt;id&gt; k=v...</code></td><td>escribir la configuración de un plugin</td></tr><tr><td><code>tiktools plugin settings reset &lt;id&gt;</code></td><td>restablecer la configuración de un plugin <strong>destructivo</strong></td></tr><tr><td><code>tiktools plugin health &lt;id&gt;</code></td><td>comprobación de salud de un plugin</td></tr><tr><td><code>tiktools plugin options &lt;action-type/field&gt;</code></td><td>opciones de un tipo de acción o campo</td></tr><tr><td><code>tiktools plugin action &lt;type&gt; [--config json] [--live]</code></td><td>ejecutar una acción de plugin</td></tr><tr><td><code>tiktools plugin commands</code></td><td>listar los comandos aportados por los plugins instalados</td></tr><tr><td><code>tiktools plugin help [id]</code></td><td>describir un comando aportado</td></tr><tr><td><code>tiktools plugin &lt;id&gt; &lt;command&gt; [--params json] [--live]</code></td><td>invocar un comando aportado por un plugin</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>listar los registros configurados</td></tr><tr><td><code>tiktools registry refresh</code></td><td>actualizar los metadatos del registro</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>mostrar un paquete del registro</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>buscar en el catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>página de resúmenes del catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>versiones de un paquete del catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>capacidades de paginación del catálogo cloud</td></tr><tr><td><code>tiktools registry defaults</code></td><td>configuración por defecto del registro</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools processor list</code></td><td>listar los procesadores</td></tr><tr><td><code>tiktools processor status</code></td><td>estado de la canalización de procesadores</td></tr><tr><td><code>tiktools processor test &lt;plugin-id&gt; &lt;processor-id&gt; [event-json]</code></td><td>ejecutar un procesador contra un evento de muestra</td></tr></tbody></table><p>Consulta la <a href="./../../developer/cli.html">referencia completa de comandos</a> para las convenciones, la salida JSON y los marcadores de operaciones destructivas.</p>`,6)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};